// Turn a form webhook or an IMAP email into one inquiry shape (SPEC §3.1).

function toE164(raw, defaultCountryCode = '1') {
  if (raw == null) return null;
  const text = String(raw).trim();
  if (!text) return null;
  const digits = text.replace(/[^\d]/g, '');
  if (text.startsWith('+')) return digits.length >= 8 && digits.length <= 15 ? `+${digits}` : null;
  if (text.startsWith('00')) return digits.length - 2 >= 8 && digits.length - 2 <= 15 ? `+${digits.slice(2)}` : null;
  if (defaultCountryCode === '1') {
    if (digits.length === 10) return `+1${digits}`;
    if (digits.length === 11 && digits.startsWith('1')) return `+${digits}`;
  }
  return null;
}

function cleanText(value) {
  const text = value == null ? '' : String(value).trim();
  return text || null;
}

function cleanEmail(value) {
  const text = cleanText(value);
  return text ? text.toLowerCase() : null;
}

function headerValue(headers, name) {
  if (!headers) return undefined;
  const key = Object.keys(headers).find((item) => item.toLowerCase() === name.toLowerCase());
  return key === undefined ? undefined : headers[key];
}

function formSubmissionId(body) {
  if (cleanText(body.submission_id)) return String(body.submission_id).trim();
  const crypto = require('crypto');
  return crypto.createHash('sha256').update(`${cleanEmail(body.email) || ''}|${cleanText(body.message) || ''}`).digest('hex').slice(0, 16);
}

function normalizeForm(body = {}, headers = {}, { demoMode = false, now = new Date().toISOString() } = {}) {
  return {
    source: 'form',
    source_id: `form:${formSubmissionId(body)}`,
    received_at: now,
    name: cleanText(body.name),
    email: cleanEmail(body.email),
    phone: toE164(body.phone),
    company: cleanText(body.company),
    subject: cleanText(body.subject) || 'Website contact form',
    message: cleanText(body.message) || '',
    demo_flags: { break_llm: Boolean(demoMode) && String(headerValue(headers, 'x-demo-break-llm') || '') === '1' },
  };
}

// mailparser addresses look like { value: [{ address, name }], text }; the simple format gives a string.
function firstAddress(field) {
  if (!field) return { address: null, name: null };
  if (typeof field === 'string') {
    const match = field.match(/^\s*"?([^"<]*?)"?\s*<([^>]+)>\s*$/);
    return match ? { address: match[2].trim(), name: match[1].trim() || null } : { address: field.trim(), name: null };
  }
  const first = Array.isArray(field.value) ? field.value[0] : null;
  return first ? { address: first.address || null, name: first.name || null } : firstAddress(field.text);
}

function stripQuotedReply(text) {
  const lines = String(text || '').replace(/\r\n/g, '\n').split('\n');
  const kept = [];
  for (const line of lines) {
    if (line === '-- ' || line.trim() === '--') break;
    if (/^On .+wrote:$/.test(line.trim())) break;
    if (line.trim().startsWith('>')) continue;
    kept.push(line);
  }
  return kept.join('\n').trim();
}

function findPhone(text) {
  const match = String(text || '').match(/(\+?\d[\d\s().-]{7,}\d)/);
  return match ? toE164(match[1]) : null;
}

function normalizeEmail(mail = {}, { selfAddress = '', now = new Date().toISOString() } = {}) {
  const from = firstAddress(mail.from);
  const replyTo = firstAddress(mail.replyTo || headerValue(mail.headers, 'reply-to'));
  const self = String(selfAddress || '').toLowerCase();
  if (!replyTo.address && from.address && from.address.toLowerCase() === self) return { skip: true, reason: 'self_sent' };
  const sender = replyTo.address ? replyTo : from;
  const message = stripQuotedReply(mail.text || mail.textPlain || '');
  const messageId = cleanText(mail.messageId || headerValue(mail.headers, 'message-id'));
  const crypto = require('crypto');
  const fallbackId = crypto.createHash('sha256').update(`${sender.address || ''}|${mail.subject || ''}|${message}`).digest('hex').slice(0, 16);
  return {
    source: 'email',
    source_id: `email:${messageId || fallbackId}`,
    received_at: mail.date ? new Date(mail.date).toISOString() : now,
    name: cleanText(sender.name || from.name),
    email: cleanEmail(sender.address),
    phone: findPhone(message),
    company: null,
    subject: cleanText(mail.subject),
    message,
    demo_flags: { break_llm: false },
  };
}

// Demo safety: only reserved example domains may reach HubSpot.
function isDemoAddress(email) {
  return /@example\.(com|org)$/i.test(String(email || ''));
}

function validateInquiry(inquiry, { demoOnly = false } = {}) {
  if (!inquiry.email && !inquiry.phone) return { valid: false, reason: 'no_contact' };
  if (inquiry.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(inquiry.email)) return { valid: false, reason: 'bad_email' };
  if (demoOnly && !isDemoAddress(inquiry.email)) return { valid: false, reason: 'non_demo_address' };
  if (String(inquiry.message || '').trim().length < 5) return { valid: false, reason: 'empty_message' };
  return { valid: true, reason: null };
}

const item = $input.first().json;
const demoMode = $env.DEMO_MODE === '1';
const inquiry = normalizeForm(item.body || {}, item.headers || {}, { demoMode });
return [{ json: { ...inquiry, validation: validateInquiry(inquiry, { demoOnly: demoMode }) } }];

// HubSpot notes, Slack texts and the run log; every number here comes from code, not the AI.

function escapeNoteHtml(value) {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const paragraph = (text) => `<p>${escapeNoteHtml(text).replace(/\n/g, '<br>')}</p>`;

function inquiryNoteHtml(inquiry, qualification) {
  return [
    paragraph(`[${inquiry.source}] ${inquiry.received_at}`),
    inquiry.subject ? paragraph(inquiry.subject) : '',
    paragraph(inquiry.message),
    paragraph(`AI: ${qualification.tier} / ${qualification.topic} / ${qualification.urgency} — ${qualification.reason}`),
  ].join('');
}

function decisionNoteHtml(result, { date, sentTo }) {
  if (result.timedOut) return paragraph('Reply drafted by AI; review timed out, nothing sent.');
  if (result.decision === 'approve') return paragraph(`Reply drafted by AI, edited: ${result.edited ? 'yes' : 'no'}, approved by ${result.reviewer} on ${date}, sent to ${sentTo}.\n\nSubject: ${result.subject}\n\n${result.body}`);
  return paragraph(`Reply drafted by AI, rejected by ${result.reviewer} on ${date}, nothing sent.`);
}

function noteRequest(contactId, html, timestamp = new Date().toISOString()) {
  return {
    properties: { hs_timestamp: timestamp, hs_note_body: html },
    associations: [{ to: { id: String(contactId) }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 202 }] }],
  };
}

function contactUrl(portalId, contactId) {
  return portalId ? `https://app.hubspot.com/contacts/${portalId}/record/0-1/${contactId}` : `https://app.hubspot.com/contacts/record/0-1/${contactId}`;
}

function maskSecrets(value) {
  return String(value ?? '')
    .replace(/Bearer\s+[^\s"']+/gi, 'Bearer ***')
    .replace(/\bsk-[A-Za-z0-9_-]+/g, '***')
    .replace(/\bpat-[A-Za-z0-9-]+/g, '***')
    .replace(/https:\/\/hooks\.slack\.com\/[^\s"']+/g, 'https://hooks.slack.com/***');
}

function formatAlert(payload = {}, baseUrl = 'http://localhost:5679') {
  const workflow = payload.workflow || {};
  const execution = payload.execution || {};
  const message = maskSecrets((execution.error && execution.error.message) || 'Unknown error');
  const url = `${baseUrl}/workflow/${workflow.id || ''}/executions/${execution.id || ''}`;
  return { text: `:rotating_light: Lead intake workflow error\nWorkflow: ${workflow.name || workflow.id || 'unknown'}\nNode: ${execution.lastNodeExecuted || 'unknown'}\nError: ${message}\n${url}`, url };
}

function rejectedInputAlert(inquiry, reason) {
  const who = inquiry.email || inquiry.phone || inquiry.name || 'unknown sender';
  return `:warning: Inquiry not accepted (${reason}) from ${who} via ${inquiry.source}. Nothing was written to HubSpot; please follow up by hand if needed.`;
}

function llmFailureAlert(inquiry, qualification, link) {
  return `:warning: AI classification failed for ${inquiry.email || inquiry.phone} (${qualification.llm_error}). The lead was saved as Needs review with no draft reply: ${link}`;
}

function reviewAlert(inquiry, qualification, reviewUrl) {
  return `:incoming_envelope: New lead: ${inquiry.name || inquiry.email} (${qualification.tier}, ${qualification.urgency} urgency) — review the draft reply: ${reviewUrl}`;
}

function buildRunLog({ inquiry, fixtureId = null, contactId = null, action, qualification = null, draft = 'none', sentTo = null, reviewer = null, edited = null, alerts = [], executionId = null }) {
  return {
    ts: new Date().toISOString(),
    execution_id: executionId,
    source_id: inquiry.source_id,
    source: inquiry.source,
    fixture_id: fixtureId,
    email: inquiry.email,
    contact_id: contactId,
    action,
    tier: qualification ? qualification.tier : null,
    llm_ok: qualification ? qualification.llm_ok : null,
    llm_error: qualification ? qualification.llm_error : null,
    draft,
    reviewer,
    edited,
    sent_to: sentTo,
    alerts,
  };
}

const inquiry = $('Normalize form').first().json;
return [{ json: { runLog: { inquiry, action: 'rejected_input', alerts: [rejectedInputAlert(inquiry, inquiry.validation.reason)] } } }];

// Human approval: review page, decision parsing and the outgoing reply (SPEC §6).

function escapeHtml(value) {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function safeId(sourceId) {
  return String(sourceId || 'unknown').replace(/[^A-Za-z0-9._-]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 80);
}

const TIER_LABEL = { qualified: 'Qualified', needs_review: 'Needs review', not_qualified: 'Not qualified' };

